import logging
import os
import re
from typing import Dict, Optional

import requests  # type: ignore
from requests.auth import HTTPBasicAuth  # type: ignore

from taf.ul.sbts.pmi_ticket_collector.utils.utils_funcs import timer  # type: ignore


class CountersDefHandler:
    COUNTERS_URI = "http://svne1.access.nsn.com/isource/svnroot/BTS_GEN_IDS/EPmCounterId_5G/trunk/EPmCounterId.h"
    CREDENTIALS = ("ca_ute_test", "utetest")
    COUNTER_REGEXP = re.compile(
        r"EPmCounterId_5G_(?P<name>[\w_]+)\n? = (?P<dev_val>\d+)[, /*]+(?P<val>[A-Z0-9]+)", re.DOTALL | re.MULTILINE
    )

    def __init__(self):
        self._logger: logging.Logger = logging.getLogger("pmi_ticket_collector.countersdefhandler")

    @timer
    def get_counter_definitions(self) -> Dict[str, Dict[str, str]]:
        data = self._download_latest_counter_definitions() or self._load_counter_definitions_offline()
        counters = self._parse_counter_data(data)
        return counters

    def _download_latest_counter_definitions(self) -> Optional[str]:
        data = ""
        try:
            self._logger.debug(f"Getting counters def from {self.COUNTERS_URI}")
            data = requests.get(self.COUNTERS_URI, auth=HTTPBasicAuth(*self.CREDENTIALS), timeout=30).text
        except Exception as err:
            self._logger.debug(f"Couldn't download latest counter definitions, will use stored one\n{err}")
        return data

    def _load_counter_definitions_offline(self) -> str:
        self._logger.debug("Reading counters def from file")
        with open(os.path.join(os.path.dirname(__file__), "utils", "EPmCounterId.h")) as counters_def:
            return counters_def.read()

    def _parse_counter_data(self, data: str) -> Dict[str, Dict[str, str]]:
        counters = {}
        matches = self.COUNTER_REGEXP.findall(data)
        for match in matches:
            name, dev_val, val = match
            counters[dev_val] = {"name": name, "value": val}
        self._logger.debug("Counters info saved")
        return counters
